// Generated by OSL (@osl/backend-drizzle-next). The Posts page: a master list of Article rows and a detail pane for the selected one.
// Do not edit: this file is rewritten on every osl generate.

"use client";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import Link from "next/link";
import { useParams, usePathname, useRouter } from "next/navigation";
import { Plus } from "lucide-react";
import { Fragment, useEffect, useState, type FormEvent, type ReactNode } from "react";
import { Badge } from "@/components/ui/badge";
import { Button, buttonVariants } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import { client, sessionUser, type Inputs, type Outputs, type SessionUser } from "../client";
import { EmptyPane, ErrorNote, FieldRow, FileInput, FilePreview, FormRow, ListSkeleton, Pagination, Pane, PaneHeader, PaneSkeleton, formatDateTime, formatList, splitList, text, yesNo } from "../ui";

type Row = Outputs["posts"]["list"]["data"][number];
type Detail = Outputs["posts"]["get"];
type Input<K extends keyof Inputs["posts"]> = Inputs["posts"][K];

const PAGE_SIZE = 20;
const KEY = ["posts"] as const;

function idOf(raw: string) {
  return raw;
}

function canCreate(user: SessionUser | null): boolean {
  return user !== null;
}

function canUpdate(user: SessionUser | null, row: Detail): boolean {
  return user !== null && row.author_id === user.id;
}

function canDelete(user: SessionUser | null, row: Detail): boolean {
  return user !== null && row.author_id === user.id;
}

function canPublish(user: SessionUser | null, row: Detail): boolean {
  return user !== null && row.author_id === user.id;
}

function canUnpublishAll(user: SessionUser | null): boolean {
  return user !== null && (user as { role?: unknown }).role === "admin";
}

const POSTS_FIELDS = ["title", "content", "published", "tags", "cover"] as const;
type PostsField = (typeof POSTS_FIELDS)[number];

type PostsValues = {
  title: string;
  content: string;
  published: boolean;
  tags: string;
  cover: string;
};

const EMPTY_POSTS: PostsValues = {
  title: "",
  content: "",
  published: false,
  tags: "",
  cover: ""
};

const POSTS_CREATE: readonly PostsField[] = ["title", "content", "published", "tags", "cover"];

function toPostsCreateInput(v: PostsValues): Input<"create"> {
  return {
    title: v.title,
    content: v.content,
    published: v.published,
    tags: (v.tags === "" ? null : splitList(v.tags)),
    cover: (v.cover || null)
  };
}

const POSTS_UPDATE: readonly PostsField[] = ["title", "content", "published", "tags", "cover"];

function toPostsUpdateInput(v: PostsValues): Input<"update">["data"] {
  return {
    title: v.title,
    content: v.content,
    published: v.published,
    tags: (v.tags === "" ? null : splitList(v.tags)),
    cover: (v.cover || null)
  };
}

function postsFromRow(row: Detail): PostsValues {
  return {
    title: text(row.title),
    content: text(row.content),
    published: row.published ?? false,
    tags: formatList(row.tags),
    cover: row.cover?.id ?? ""
  };
}

type PostsSetter = <K extends keyof PostsValues>(key: K, value: PostsValues[K]) => void;

function renderPostsField(field: PostsField, values: PostsValues, set: PostsSetter, current?: Detail | null) {
  switch (field) {
    case "title":
      return (
      <FormRow label="Title" htmlFor="title">
        <Input id="title" type="text" maxLength={200} value={values.title} onChange={e => set("title", e.target.value)} required />
      </FormRow>
      );
    case "content":
      return (
      <FormRow label="Content" htmlFor="content">
        <Textarea id="content" rows={4} value={values.content} onChange={e => set("content", e.target.value)} required />
      </FormRow>
      );
    case "published":
      return (
      <div className="flex items-center gap-2">
        <Checkbox id="published" checked={values.published} onCheckedChange={checked => set("published", checked)} />
        <Label htmlFor="published">Published</Label>
      </div>
      );
    case "tags":
      return (
      <FormRow label="Tags" htmlFor="tags">
        <Input id="tags" type="text" placeholder="comma, separated" value={values.tags} onChange={e => set("tags", e.target.value)} />
      </FormRow>
      );
    case "cover":
      return (
      <FormRow label="Cover" htmlFor="cover">
        <FileInput id="cover" value={values.cover} current={current?.cover} accept="image/*" onChange={fileId => set("cover", fileId)} />
      </FormRow>
      );
  }
}

function PostsForm({
  fields,
  initial,
  current,
  submitLabel,
  pending,
  error,
  onSubmit,
  onCancel
}: {
  fields: readonly PostsField[];
  initial: PostsValues;
  current?: Detail | null;
  submitLabel: string;
  pending: boolean;
  error: { message: string } | null;
  onSubmit: (values: PostsValues) => void;
  onCancel?: () => void;
}) {
  const [values, setValues] = useState<PostsValues>(initial);
  const [problem, setProblem] = useState<string | null>(null);
  const set: PostsSetter = (key, value) => setValues(current => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => {
    event.preventDefault();
    setProblem(null);
    try {
      onSubmit(values);
    } catch (err) {
      setProblem(err instanceof Error ? err.message : String(err));
    }
  };
  return (
    <form onSubmit={submit} className="grid max-w-xl gap-4">
      {fields.map(field => (
        <Fragment key={field}>{renderPostsField(field, values, set, current)}</Fragment>
      ))}
      <ErrorNote error={error ?? (problem ? { message: problem } : null)} />
      <div className="flex gap-2">
        <Button type="submit" disabled={pending}>
          {submitLabel}
        </Button>
        {onCancel ? (
          <Button type="button" variant="ghost" onClick={onCancel}>
            Cancel
          </Button>
        ) : null}
      </div>
    </form>
  );
}

export function PostsLayout({ children }: { children: ReactNode }) {
  const [page, setPage] = useState(1);
  const [openAction, setOpenAction] = useState<string | null>(null);
  void openAction;
  void setOpenAction;
  const input = { page, page_size: PAGE_SIZE } as Inputs["posts"]["list"];
  const list = useQuery({ queryKey: [...KEY, "list", input], queryFn: () => client.posts.list(input) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const pathname = usePathname();
  const queryClient = useQueryClient();
  const unpublish_allAction = useMutation({
    mutationFn: (input: Inputs["posts"]["unpublish_all"]) => client.posts.unpublish_all(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  return (
    <div className="flex h-full min-h-0">
      <aside className="flex w-80 shrink-0 flex-col border-r border-border">
        <PaneHeader title="Posts" count={list.data?.page.total}>
          {canCreate(user) ? (
            <Link href="/posts/new" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="New article">
              <Plus />
            </Link>
          ) : null}
          {canUnpublishAll(user) ? (
            <Button variant="outline" size="sm" disabled={unpublish_allAction.isPending} onClick={() => unpublish_allAction.mutate({})}>
              Unpublish All
            </Button>
          ) : null}
        </PaneHeader>

        <ErrorNote error={unpublish_allAction.error} className="m-4" />
        <div className="min-h-0 flex-1 overflow-y-auto">
          {list.isPending ? (
            <ListSkeleton />
          ) : list.error ? (
            <ErrorNote error={list.error} className="m-4" />
          ) : list.data.data.length === 0 ? (
            <EmptyPane>No posts yet.</EmptyPane>
          ) : (
            <ul className="py-1">
              {list.data.data.map((row: Row) => (
                <li key={text(row.id)}>
                  <Link
                    href={`/posts/${text(row.id)}`}
                    className={cn("block border-l-2 border-transparent px-4 py-2 hover:bg-accent/60", pathname === `/posts/${text(row.id)}` && "border-primary bg-accent")}
                  >
                    <div className="truncate text-sm font-medium">{text(row.title) || "Article " + text(row.id)}</div>
                    <div className="truncate text-xs text-muted-foreground">{[(row.published ? "Published" : "Not published"), formatDateTime(row.posted_at)].filter(Boolean).join(" · ")}</div>
                  </Link>
                </li>
              ))}
            </ul>
          )}
        </div>
        {list.data ? <Pagination page={page} pageSize={PAGE_SIZE} total={list.data.page.total} onChange={setPage} /> : null}
      </aside>
      <section className="min-w-0 flex-1 overflow-y-auto">
        {children}
      </section>
    </div>
  );
}

export function PostsIndex() {
  return <EmptyPane>Select an article from the list, or create one.</EmptyPane>;
}

export function PostsNew() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.posts.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push(`/posts/${text(row.id)}`);
    }
  });
  return (
    <Pane title="New article">
      <PostsForm
        fields={POSTS_CREATE}
        initial={EMPTY_POSTS}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toPostsCreateInput(values))}
      />
    </Pane>
  );
}

export function PostsDetail() {
  const { id: rawId } = useParams<{ id: string }>();
  const id = idOf(rawId);
  const router = useRouter();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  const [openAction, setOpenAction] = useState<string | null>(null);
  useEffect(() => {
    setEditing(false);
    setOpenAction(null);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.posts.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["posts"]["update"]) => client.posts.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["posts"]["delete"]) => client.posts.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push("/posts");
    }
  });
  const publishAction = useMutation({
    mutationFn: (input: Inputs["posts"]["publish"]) => client.posts.publish(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <ErrorNote error={query.error} className="m-6" />;
  const row: Detail = query.data;
  return (
    <Pane
      title={text(row.title) || "Article " + text(row.id)}
      actions={
        <>
          {canPublish(user, row) ? (
            <Button variant="outline" size="sm" disabled={publishAction.isPending} onClick={() => publishAction.mutate({ id })}>
              Publish
            </Button>
          ) : null}
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this article?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >

      <ErrorNote error={publishAction.error} className="mb-4" />
      {editing ? (
        <PostsForm
          fields={POSTS_UPDATE}
          initial={postsFromRow(row)}
          current={row}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toPostsUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Title">{text(row.title) || "—"}</FieldRow>
        <FieldRow label="Content">
          <p className="whitespace-pre-wrap">{text(row.content) || "—"}</p>
        </FieldRow>
        <FieldRow label="Published">{row.published == null ? "—" : <Badge variant={row.published ? "default" : "outline"}>{yesNo(row.published)}</Badge>}</FieldRow>
        <FieldRow label="Cover">
          <FilePreview file={row.cover} />
        </FieldRow>
        <FieldRow label="Tags">
          <span className="flex flex-wrap gap-1">
            {(row.tags ?? []).map(item => (
              <Badge key={text(item)} variant="secondary">
                {text(item)}
              </Badge>
            ))}
          </span>
        </FieldRow>
        <FieldRow label="Posted At">{formatDateTime(row.posted_at) || "—"}</FieldRow>
        <FieldRow label="Author">{(row.author ? text(row.author.name) : text(row.author_id)) || "—"}</FieldRow>
        </dl>
      )}
    </Pane>
  );
}
